/// Checks whether the given vector of characters `v` is non-empty
/// and consists entirely of lowercase ASCII letters 'a'..='z'.
fn check_all_lowercase(v: &Vec<char>) -> bool {
    // First ensure it's not empty,
    // then verify every character lies in the range 'a'..='z'.
    !v.is_empty() && v.iter().all(|&c| c >= 'a' && c <= 'z')
}

/// Given an input vector of characters, returns either `vec!['a']` if
/// the input is non-empty and all lowercase, or `vec!['A']` otherwise.
fn solve(input: Vec<char>) -> Vec<char> {
    if check_all_lowercase(&input) {
        vec!['a']
    } else {
        vec!['A']
    }
}

